"""Reviewed, localized product manual. No Markdown/HTML from users is rendered."""
LANGS=('de','en','es','fr')
def tr(values,lang):return values[LANGS.index(lang if lang in LANGS else 'de')]
CATEGORIES={
 'installation':('Installation & Einstieg','Installation and first steps','Instalación y primeros pasos','Installation et premiers pas'),
 'settings':('Einstellungen & Verbindungen','Settings and connections','Ajustes y conexiones','Paramètres et connexions'),
 'functions':('Funktionen & Steuerung','Features and control','Funciones y control','Fonctions et commandes'),
 'operations':('Betrieb & Wartung','Operation and maintenance','Operación y mantenimiento','Exploitation et maintenance'),
}
GUIDES=[]
def guide(slug,category,title,steps,links=(),commands=()):
 GUIDES.append(dict(slug=slug,category=category,title=title,steps=steps,links=links,commands=commands))

guide('linux','installation',('Linux-Vollinstallation','Full Linux installation','Instalación completa en Linux','Installation Linux complète'),[
 ('Die Vollinstallation ist für Ubuntu 26.04 amd64 mit systemd, mdadm, Docker Engine und Compose geprüft. Rootless Docker und UID-Remapping werden vom Host-Adapter nicht unterstützt. Bestehende RAID- und Alarmkonfiguration vorher prüfen.','The full installation is tested on Ubuntu 26.04 amd64 with systemd, mdadm, Docker Engine and Compose. The host adapter does not support rootless Docker or UID remapping. Check existing RAID and alert configuration first.','La instalación completa está probada en Ubuntu 26.04 amd64 con systemd, mdadm, Docker Engine y Compose. El adaptador no admite Docker rootless ni reasignación de UID. Revisa primero RAID y las alertas existentes.','L’installation complète est testée sur Ubuntu 26.04 amd64 avec systemd, mdadm, Docker Engine et Compose. L’adaptateur ne prend pas en charge Docker rootless ni le remappage des UID. Vérifiez d’abord le RAID et les alertes existantes.'),
 ('Quellpaket herunterladen oder Repository klonen. Im Projektverzeichnis sudo python3 tools/install.py ausführen. Eigene Telegram-/Discord-Identitäten und Tokens im Terminal eingeben; OpenAI und Healthchecks sind optional. Zugangsdaten niemals in Clone-URLs oder Chats einfügen.','Download the source package or clone the repository. Run sudo python3 tools/install.py in its directory. Enter your own Telegram/Discord identities and tokens in the terminal; OpenAI and Healthchecks are optional. Never put credentials into clone URLs or chats.','Descarga el código o clona el repositorio. Ejecuta sudo python3 tools/install.py en su directorio. Introduce tus identidades y tokens de Telegram/Discord en la terminal; OpenAI y Healthchecks son opcionales. No pongas credenciales en URLs de clonación ni chats.','Téléchargez les sources ou clonez le dépôt. Exécutez sudo python3 tools/install.py dans son répertoire. Saisissez vos identifiants et tokens Telegram/Discord dans le terminal ; OpenAI et Healthchecks sont facultatifs. Ne placez jamais de secrets dans une URL de clonage ou un chat.'),
 ('Der Installer sichert und migriert eine kompatible Einrichtung. Ein vorhandenes Docker-Projekt wird nicht blind überschrieben. Host-Agenten bleiben außerhalb der Container. SSH-Zugang und RAID-Mitglieder werden nicht verändert. Danach /status und /automatik_status in beiden Bots prüfen.','The installer backs up and migrates a compatible setup. An existing Docker project is not blindly overwritten. Host agents stay outside containers. SSH access and RAID members are unchanged. Afterwards check /status and /automatik_status in both bots.','El instalador respalda y migra una configuración compatible. No sobrescribe a ciegas un proyecto Docker existente. Los agentes permanecen fuera de los contenedores. No modifica SSH ni miembros RAID. Después comprueba /status y /automatik_status en ambos bots.','L’installateur sauvegarde et migre une installation compatible. Il n’écrase pas aveuglément un projet Docker existant. Les agents restent hors des conteneurs. SSH et les membres RAID sont préservés. Vérifiez ensuite /status et /automatik_status dans les deux bots.'),
],commands=('sudo python3 tools/install.py',),links=(('Docker Engine','https://docs.docker.com/engine/install/ubuntu/'),))

guide('portable','installation',('Docker unter Linux & Windows','Docker on Linux and Windows','Docker en Linux y Windows','Docker sous Linux et Windows'),[
 ('Die portable Variante benötigt Linux-Container. Unter Windows Server ist eine Linux-VM mit Docker Engine erforderlich; native Windows-Container und Windows-Hostaktionen sind nicht implementiert. Ein Windows-PC benötigt eine vom Hersteller unterstützte Linux-Container-Umgebung.','The portable variant needs Linux containers. Windows Server requires a Linux VM with Docker Engine; native Windows containers and Windows host actions are not implemented. A Windows PC needs a vendor-supported Linux-container environment.','La variante portable necesita contenedores Linux. Windows Server requiere una VM Linux con Docker Engine; no hay contenedores Windows nativos ni acciones sobre Windows. Un PC Windows necesita un entorno de contenedores Linux compatible con el fabricante.','La variante portable nécessite des conteneurs Linux. Windows Server exige une VM Linux avec Docker Engine ; les conteneurs Windows natifs et les actions sur l’hôte Windows ne sont pas implémentés. Un PC Windows nécessite un environnement Linux pris en charge par le fournisseur.'),
 ('Im Projektverzeichnis den untenstehenden Compose-Befehl ausführen. Auf demselben Rechner http://127.0.0.1:8787/setup öffnen und Passwort anlegen. Das Volume portal-state enthält private Konfiguration und darf nicht weitergegeben werden.','Run the Compose command below in the project directory. On that same machine open http://127.0.0.1:8787/setup and set a password. The portal-state volume contains private configuration and must not be distributed.','Ejecuta el comando Compose de abajo en el proyecto. En ese mismo equipo abre http://127.0.0.1:8787/setup y crea la contraseña. El volumen portal-state contiene configuración privada y no debe distribuirse.','Exécutez la commande Compose ci-dessous dans le projet. Sur cette même machine, ouvrez http://127.0.0.1:8787/setup et définissez un mot de passe. Le volume portal-state contient des données privées et ne doit pas être distribué.'),
 ('Ohne Host-Adapter speichert diese Variante nur Einstellungen: keine laufenden Bots, keine Servermesswerte und keine Installations- oder Reparaturaktionen. Deaktivierte Schaltflächen sind hier beabsichtigt.','Without a host adapter this variant only stores settings: no running bots, server metrics, installations or repairs. Disabled controls are intentional.','Sin adaptador del servidor esta variante solo guarda ajustes: no ejecuta bots, métricas, instalaciones ni reparaciones. Los controles desactivados son intencionados.','Sans adaptateur hôte, cette variante conserve uniquement les paramètres : aucun bot actif, mesure serveur, installation ou réparation. Les commandes désactivées sont intentionnelles.'),
],commands=('docker compose -f compose.portable.yaml up -d --build --wait',),links=(('Docker Desktop','https://docs.docker.com/desktop/'),))

guide('access','settings',('Anmeldung, Passwort & HTTPS','Sign-in, password and HTTPS','Acceso, contraseña y HTTPS','Connexion, mot de passe et HTTPS'),[
 ('Bei der ersten Einrichtung /setup öffnen. Es gibt kein Standardpasswort und keinen Einrichtungscode. Mindestens 8 Zeichen, ein Großbuchstabe, eine Zahl und ein Sonderzeichen; keine Leerzeichen. Bei öffentlichem HTTPS ist die Ersteinrichtung auf die Administrator-IP beschränkt.','Open /setup for first setup. There is no default password or setup code. Use at least 8 characters including an uppercase letter, a number and a special character, with no whitespace. Public HTTPS first setup is restricted to the administrator IP.','Abre /setup al configurar por primera vez. No hay contraseña predeterminada ni código. Usa al menos 8 caracteres con mayúscula, número y símbolo, sin espacios. La configuración inicial por HTTPS público se limita a la IP del administrador.','Ouvrez /setup lors de la première configuration. Aucun mot de passe par défaut ni code. Utilisez au moins 8 caractères dont une majuscule, un chiffre et un caractère spécial, sans espace. L’initialisation HTTPS publique est limitée à l’IP de l’administrateur.'),
 ('Einstellungen → Passwort ändern verlangt das bisherige Passwort. Eine Änderung macht bestehende Sitzungen ungültig. Bei vergessenem Passwort ist ein administrativer Reset per bestehendem Serverzugang nötig; siehe DISTRIBUTION.md. Cookies für die Seite zulassen.','Settings → Change password requires the current password. A change invalidates existing sessions. A forgotten password needs an administrative reset through existing server access; see DISTRIBUTION.md. Allow cookies for this site.','Ajustes → Cambiar contraseña requiere la contraseña actual. El cambio invalida las sesiones. Si la olvidas, hace falta un restablecimiento administrativo mediante el acceso existente al servidor; consulta DISTRIBUTION.md. Permite cookies para este sitio.','Paramètres → Modifier le mot de passe exige le mot de passe actuel. La modification invalide les sessions. En cas d’oubli, une réinitialisation administrative via l’accès serveur existant est nécessaire ; voir DISTRIBUTION.md. Autorisez les cookies du site.'),
 ('Standardmäßig ist Port 8787 nur lokal erreichbar. Für Fernzugriff einen regulären SSH-Tunnel oder den HTTPS-Installer mit eigener öffentlicher IP nutzen. Bei öffentlichem Betrieb benötigt nginx TCP 443 und die Zertifikatserneuerung TCP 80. Port 8787 nicht öffentlich freigeben.','Port 8787 is local-only by default. Use a regular SSH tunnel or the HTTPS installer with your public IP for remote access. Public deployment needs TCP 443 for nginx and TCP 80 for certificate renewal. Do not expose port 8787 publicly.','El puerto 8787 solo es local por defecto. Para acceso remoto usa un túnel SSH normal o el instalador HTTPS con tu IP pública. El despliegue público necesita TCP 443 para nginx y TCP 80 para renovar certificados. No publiques el puerto 8787.','Le port 8787 reste local par défaut. Utilisez un tunnel SSH habituel ou l’installateur HTTPS avec votre IP publique. Le déploiement public nécessite TCP 443 pour nginx et TCP 80 pour renouveler les certificats. N’exposez pas publiquement le port 8787.'),
],commands=('sudo python3 tools/install_https.py --address YOUR_PUBLIC_IP',))

guide('telegram','settings',('Telegram: Token & Benutzer-ID','Telegram: token and user ID','Telegram: token e ID de usuario','Telegram : token et identifiant utilisateur'),[
 ('BotFather über den offiziellen Link öffnen. Mit /newbot einen Bot erstellen oder mit /mybots einen bestehenden auswählen und dessen API-Token verwalten. Token ausschließlich im eigenen Installationsdialog oder unter Einstellungen → Telegram eingeben.','Open BotFather through the official link. Use /newbot to create a bot or /mybots to select an existing one and manage its API token. Enter the token only in your installer or Settings → Telegram.','Abre BotFather desde el enlace oficial. Usa /newbot para crear un bot o /mybots para elegir uno existente y gestionar el token. Introdúcelo solo en el instalador o en Ajustes → Telegram.','Ouvrez BotFather via le lien officiel. Utilisez /newbot pour créer un bot ou /mybots pour choisir un bot existant et gérer son token. Saisissez-le uniquement dans l’installateur ou Paramètres → Telegram.'),
 ('Die numerische persönliche Telegram-ID in die Zugriffsliste eintragen, nicht den @Benutzernamen. Die ID entspricht dem user.id beziehungsweise from.id eines eigenen privaten Bot-Updates. Bei einer frischen Installation kann der Administrator diese über die Bot API vor Start des Pollings feststellen; getUpdates nicht parallel zum laufenden Bot abfragen.','Enter the numeric personal Telegram ID in the allowlist, not the @username. It is the user.id or from.id of your own private bot update. For a fresh installation an administrator can obtain it using the Bot API before polling starts; do not run getUpdates alongside the live bot.','Introduce el ID numérico personal de Telegram en la lista permitida, no el @usuario. Corresponde a user.id o from.id de tu actualización privada. En una instalación nueva el administrador puede obtenerlo con la Bot API antes del polling; no uses getUpdates en paralelo al bot activo.','Saisissez l’identifiant Telegram personnel numérique, pas le @pseudo. Il correspond à user.id ou from.id d’une mise à jour privée vous appartenant. Pour une installation neuve, l’administrateur peut l’obtenir via la Bot API avant le polling ; n’utilisez pas getUpdates en parallèle du bot actif.'),
 ('Bot im privaten Chat starten, dann /status prüfen. Nur freigegebene Benutzer in privaten Chats werden akzeptiert. Ein leeres Token-Feld behält den gespeicherten Wert. Ein offengelegtes Token bei BotFather ersetzen und anschließend hier aktualisieren.','Start the bot in a private chat, then test /status. Only allowlisted users in private chats are accepted. An empty token field keeps the saved value. Replace a leaked token in BotFather and then update it here.','Inicia el bot en un chat privado y prueba /status. Solo se aceptan usuarios autorizados en privado. Dejar vacío el campo conserva el token. Si se filtra, reemplázalo en BotFather y actualízalo aquí.','Démarrez le bot dans un chat privé puis testez /status. Seuls les utilisateurs autorisés en privé sont acceptés. Un champ vide conserve le token enregistré. Remplacez un token divulgué dans BotFather puis mettez-le à jour ici.'),
],links=(('BotFather','https://t.me/BotFather'),('Telegram Bot API','https://core.telegram.org/bots/api'),('Telegram tutorial','https://core.telegram.org/bots/tutorial')))

guide('discord','settings',('Discord: Bot, Token & IDs','Discord: bot, token and IDs','Discord: bot, token e IDs','Discord : bot, token et identifiants'),[
 ('Im Developer Portal eine eigene Anwendung erstellen. Unter Bot den Bot-Token erzeugen beziehungsweise zurücksetzen und direkt unter Einstellungen → Discord einfügen. Die Application ID findet sich unter General Information. Public Key und Client Secret sind kein Bot-Token.','Create your own application in the Developer Portal. Generate or reset the bot token under Bot and enter it directly in Settings → Discord. Find Application ID under General Information. Public Key and Client Secret are not the bot token.','Crea tu aplicación en Developer Portal. Genera o restablece el token en Bot e introdúcelo en Ajustes → Discord. Application ID está en General Information. Public Key y Client Secret no son el token del bot.','Créez votre application dans le Developer Portal. Générez ou réinitialisez le token dans Bot et saisissez-le dans Paramètres → Discord. Application ID se trouve dans General Information. Public Key et Client Secret ne sont pas le token du bot.'),
 ('In Discord unter Benutzereinstellungen → Erweitert den Entwicklermodus einschalten. Benutzer, Server und privaten Textkanal rechts anklicken und die jeweilige ID kopieren. Alle vier IDs und den Token in die zugehörigen Felder eintragen.','Enable Developer Mode in Discord User Settings → Advanced. Right-click the user, server and private text channel to copy their IDs. Enter all four IDs and the token into the corresponding fields.','Activa Developer Mode en Ajustes de usuario → Avanzado. Haz clic derecho sobre usuario, servidor y canal privado para copiar sus IDs. Introduce los cuatro IDs y el token en sus campos.','Activez Developer Mode dans Paramètres utilisateur → Avancé. Faites un clic droit sur l’utilisateur, le serveur et le salon privé pour copier leurs identifiants. Saisissez les quatre identifiants et le token dans leurs champs.'),
 ('Bot mit den Scopes bot und applications.commands auf den eigenen Server einladen. Nur die benötigten Kanalrechte vergeben, keine Administratorrechte. Privilegierte Intents werden nicht benötigt. /status im erlaubten Kanal testen; DMs und andere Benutzer/Kanäle werden abgewiesen.','Invite the bot to your server with bot and applications.commands scopes. Grant only required channel permissions, not Administrator. Privileged intents are not needed. Test /status in the allowed channel; DMs and other users/channels are rejected.','Invita el bot con scopes bot y applications.commands. Concede solo permisos necesarios del canal, sin Administrador. No necesita intents privilegiados. Prueba /status en el canal permitido; se rechazan mensajes privados y otros usuarios/canales.','Invitez le bot avec les scopes bot et applications.commands. Accordez seulement les permissions nécessaires du salon, sans Administrateur. Aucun intent privilégié requis. Testez /status dans le salon autorisé ; les messages privés et autres utilisateurs/salons sont refusés.'),
],links=(('Discord Developer Portal','https://discord.com/developers/applications'),('Discord IDs','https://support.discord.com/hc/en-us/articles/206346498-Where-can-I-find-my-User-Server-Message-ID'),('Discord developer guide','https://docs.discord.com/developers/quick-start/getting-started')))

guide('openai','settings',('OpenAI: API-Schlüssel & KI','OpenAI: API key and AI','OpenAI: clave API e IA','OpenAI : clé API et IA'),[
 ('Die API-Key-Seite öffnen, eigenes Projekt wählen und einen neuen geheimen Schlüssel erstellen. Den Schlüssel unmittelbar unter Einstellungen → OpenAI einfügen. Nutzungsberechtigung, Modellzugang und Abrechnung des eigenen API-Projekts prüfen. Keine Zugangsdaten im Chat senden.','Open the API keys page, choose your project and create a new secret key. Enter it directly in Settings → OpenAI. Check your API project’s permissions, model access and billing. Never send credentials in chat.','Abre API keys, elige tu proyecto y crea una clave secreta nueva. Introdúcela directamente en Ajustes → OpenAI. Revisa permisos, acceso al modelo y facturación del proyecto. Nunca envíes credenciales por chat.','Ouvrez API keys, choisissez votre projet et créez une clé secrète. Saisissez-la directement dans Paramètres → OpenAI. Vérifiez les autorisations, l’accès au modèle et la facturation du projet. N’envoyez jamais d’identifiants dans un chat.'),
 ('Der Schlüssel ist optional. Ohne ihn bleiben Status und direkte bestätigte Paketaktionen verfügbar. Leeres Feld behält den bisherigen Wert; die ausdrückliche Löschoption entfernt ihn. Gespeicherte Schlüssel werden nicht an den Browser zurückgegeben.','The key is optional. Status and direct confirmed package actions remain available without it. An empty field keeps the current key; the explicit removal option deletes it. Saved keys are not returned to the browser.','La clave es opcional. Estado y acciones directas confirmadas siguen disponibles sin ella. Un campo vacío conserva la clave; la opción explícita la elimina. Las claves guardadas no se devuelven al navegador.','La clé est facultative. État et actions directes confirmées restent disponibles sans elle. Un champ vide conserve la clé ; l’option explicite la supprime. Les clés enregistrées ne sont pas renvoyées au navigateur.'),
 ('/ki sendet Auftrag und feste Statusmesswerte an OpenAI. Keine Geheimnisse in Fragen eingeben. Bei Installationswünschen wird ein echter APT-Plan vorbereitet; KI-Text wird niemals als Shell-Befehl ausgeführt. Erst eine eigene Bestätigung erlaubt die Installation.','/ki sends the request and fixed status readings to OpenAI. Do not include secrets in questions. Installation requests prepare a real APT plan; AI text is never executed as a shell command. A separate confirmation authorizes installation.','/ki envía la solicitud y mediciones fijas a OpenAI. No incluyas secretos. Las solicitudes de instalación preparan un plan APT real; el texto de IA nunca se ejecuta como shell. La instalación necesita confirmación aparte.','/ki envoie la demande et des mesures prédéfinies à OpenAI. N’incluez aucun secret. Les demandes d’installation préparent un vrai plan APT ; le texte de l’IA n’est jamais exécuté dans un shell. Une confirmation distincte autorise l’installation.'),
],links=(('OpenAI API keys','https://platform.openai.com/api-keys'),('OpenAI production guidance','https://developers.openai.com/api/docs/guides/production-best-practices')))

guide('healthchecks','settings',('Healthchecks: Lebenszeichen & Alarme','Healthchecks: heartbeats and alerts','Healthchecks: señales y alertas','Healthchecks : signaux de vie et alertes'),[
 ('Im eigenen Healthchecks-Konto zwei getrennte Checks für Server und Bot anlegen. Die jeweiligen UUID-Ping-URLs kopieren und unter Einstellungen → Healthchecks zuordnen. Benötigt werden Ping-URLs, kein Management-API-Schlüssel.','Create separate server and bot checks in your Healthchecks account. Copy their UUID ping URLs and assign them in Settings → Healthchecks. Ping URLs are required, not a management API key.','Crea checks separados para servidor y bot en Healthchecks. Copia sus URLs de ping UUID y asígnalas en Ajustes → Healthchecks. Se necesitan URLs de ping, no una clave API de gestión.','Créez des checks distincts pour le serveur et le bot dans Healthchecks. Copiez leurs URL de ping UUID et affectez-les dans Paramètres → Healthchecks. Des URL de ping sont requises, pas une clé API de gestion.'),
 ('Empfänger beziehungsweise Integrationen im Healthchecks-Konto einrichten. Zeitraum und Toleranz auf die tatsächlichen Lebenszeichen abstimmen. Ein kontrollierter Alarmtest muss getrennt zeigen, dass der Check ausfällt und die Warnung beim Empfänger ankommt.','Configure recipients or integrations in Healthchecks. Match period and grace time to actual heartbeat intervals. A controlled alert test must separately verify the check goes down and the recipient receives the warning.','Configura destinatarios o integraciones en Healthchecks. Ajusta período y tolerancia al intervalo real. Una prueba controlada debe verificar tanto la caída del check como la recepción del aviso.','Configurez les destinataires ou intégrations dans Healthchecks. Adaptez période et délai de grâce aux signaux réels. Un test contrôlé doit vérifier séparément la panne du check et la réception de l’alerte.'),
 ('Beide Felder sind optional. Ping-URLs wie Passwörter behandeln und nicht ins Repository kopieren. Ausbleibende Lebenszeichen sind keine vollständige Festplatten- oder Anwendungsdiagnose.','Both fields are optional. Treat ping URLs like passwords and keep them out of the repository. Missing heartbeats are not a complete disk or application diagnosis.','Ambos campos son opcionales. Trata las URLs como contraseñas y no las copies al repositorio. La falta de señales no es un diagnóstico completo de discos ni aplicaciones.','Les deux champs sont facultatifs. Traitez les URL comme des mots de passe et ne les placez pas dans le dépôt. L’absence de signaux n’est pas un diagnostic complet des disques ou applications.'),
],links=(('Healthchecks checks','https://healthchecks.io/checks/'),('Healthchecks documentation','https://healthchecks.io/docs/')))

guide('monitoring','settings',('RAID-Überwachung & Automatik','RAID monitoring and automation','Supervisión RAID y automatización','Surveillance RAID et automatisation'),[
 ('Unter Einstellungen → Überwachung nur vorhandene md-Gerätenamen wie md4 eintragen. RAID-Mitglieder, Partitionen und Synchronisation werden nicht verändert. Ein Resync bei degraded=0 ist kein Nachweis eines Plattenausfalls.','In Settings → Monitoring enter existing md device names such as md4. RAID members, partitions and synchronization are not changed. A resync with degraded=0 is not proof of disk failure.','En Ajustes → Supervisión introduce dispositivos md existentes, por ejemplo md4. No cambia miembros RAID, particiones ni sincronización. Un resync con degraded=0 no prueba un fallo de disco.','Dans Paramètres → Surveillance, saisissez des périphériques md existants, comme md4. Membres RAID, partitions et synchronisation restent inchangés. Un resync avec degraded=0 ne prouve pas une panne de disque.'),
 ('Die Automatik prüft alle 60 Sekunden. Nur eine mindestens 120 Sekunden anhaltende Störung der getesteten RAID-Monitor-Dienste darf repariert werden. Grenzen: eine Stunde Abstand, höchstens drei Versuche in 24 Stunden und gemeinsamer 120-Sekunden-Cooldown.','Automation checks every 60 seconds. Only a fault persisting for at least 120 seconds in the tested RAID-monitor services permits repair. Limits: one hour between attempts, at most three in 24 hours and a shared 120-second cooldown.','La automatización revisa cada 60 segundos. Solo repara fallos de al menos 120 segundos en los servicios probados del monitor RAID. Límites: una hora entre intentos, máximo tres en 24 horas y espera compartida de 120 segundos.','L’automatisation vérifie toutes les 60 secondes. Seule une panne d’au moins 120 secondes des services RAID testés autorise une réparation. Limites : une heure entre essais, trois au maximum par 24 heures et délai partagé de 120 secondes.'),
 ('/automatik_status zeigt Zustand, letzte Versuche und Sperrzeiten. /automatik_an und /automatik_aus schalten dauerhaft um. Telegram-Vorankündigung ist vor jeder automatischen Reparatur erforderlich; Ergebnisse bleiben bis zur Zustellung gespeichert. Fehler oder unklare Ergebnisse sperren bis erfolgreichem manuellem /raid_monitor_start.','/automatik_status shows state, recent attempts and lock times. /automatik_an and /automatik_aus persistently toggle automation. Telegram preannouncement is required before each automatic repair; results remain until delivered. Failure or uncertainty locks automation until successful manual /raid_monitor_start.','/automatik_status muestra estado, intentos y bloqueos. /automatik_an y /automatik_aus guardan el cambio. Cada reparación automática requiere aviso previo por Telegram; el resultado se guarda hasta entregarlo. Fallos o resultados inciertos bloquean hasta un /raid_monitor_start manual exitoso.','/automatik_status affiche état, essais et délais. /automatik_an et /automatik_aus conservent le réglage. Chaque réparation automatique exige une annonce Telegram préalable ; les résultats restent jusqu’à livraison. Un échec ou doute bloque jusqu’à un /raid_monitor_start manuel réussi.'),
 ('Die freigegebene Reparatur betrifft ausschließlich mdmonitor.service und mdmonitor-oneshot.service. Ein erfolgreich inaktiver oneshot-Dienst ist normal. Dies ist keine SMART-Prüfung oder automatische Reparatur von Laufwerken.','The approved repair only affects mdmonitor.service and mdmonitor-oneshot.service. A successfully inactive oneshot service is normal. This is not a SMART test or automatic disk repair.','La reparación permitida solo afecta a mdmonitor.service y mdmonitor-oneshot.service. Un oneshot inactivo tras éxito es normal. No es una prueba SMART ni reparación automática de discos.','La réparation autorisée concerne uniquement mdmonitor.service et mdmonitor-oneshot.service. Un service oneshot inactif après réussite est normal. Il ne s’agit pas d’un test SMART ni d’une réparation automatique de disques.'),
])

guide('status','functions',('Status, CPU-Kerne & Darstellung','Status, CPU cores and appearance','Estado, núcleos y apariencia','État, cœurs et apparence'),[
 ('Status zeigt Host-CPU, alle logischen CPU-Kerne, RAM, Laufzeit, Laufwerke, Dateisysteme, Netzwerkraten und zugewiesene IP-Adressen. Aktualisierung alle drei Sekunden im sichtbaren Tab. CPU und Netzwerkraten benötigen zwei Messungen; beim Verbindungsfehler bleiben Werte als veraltet markiert.','Status shows host CPU, every logical core, RAM, uptime, disks, filesystems, network rates and assigned IP addresses. Visible tabs update every three seconds. CPU and network rates need two samples; lost connections mark readings stale.','Estado muestra CPU del servidor, todos los núcleos lógicos, RAM, tiempo activo, discos, sistemas de archivos, tasas de red e IP asignadas. Actualiza cada tres segundos en pestañas visibles. CPU y red necesitan dos muestras; una desconexión marca datos obsoletos.','État affiche CPU de l’hôte, tous les cœurs logiques, RAM, durée d’activité, disques, systèmes de fichiers, débits et IP attribuées. Actualisation toutes les trois secondes dans un onglet visible. CPU et réseau exigent deux mesures ; une déconnexion marque les données périmées.'),
 ('Oben stehen lokale Uhrzeit und separat Serverzeit mit Zeitzone. Designmenü: Ruby Control oder Crimson Glass, je Rot/Blau/Grün/Lila/Anthrazit und Tag/Nacht. Das Menü lässt sich einklappen; Sprache unten links wählen. Die Auswahl bleibt für diesen Browser gespeichert.','The header shows local time and separate server time with its timezone. Choose Ruby Control or Crimson Glass, each in red/blue/green/purple/anthracite and light/dark. Collapse the menu and choose a language at bottom left. Preferences are saved for this browser.','La cabecera muestra hora local y hora del servidor con zona. Elige Ruby Control o Crimson Glass en rojo/azul/verde/morado/antracita y claro/oscuro. El menú se contrae; idioma abajo a la izquierda. Se guardan las preferencias en este navegador.','L’en-tête affiche heure locale et heure serveur avec fuseau. Choisissez Ruby Control ou Crimson Glass, en rouge/bleu/vert/violet/anthracite et clair/sombre. Le menu est repliable ; langue en bas à gauche. Les préférences sont conservées pour ce navigateur.'),
])

guide('packages','functions',('KI & Paketinstallationen','AI and package installation','IA e instalación de paquetes','IA et installation de paquets'),[
 ('/ki Installiere nginx erkennt einen Installationswunsch und bereitet einen APT-Plan vor. /ki_install nginx fordert den Plan ohne KI an. Auf der Steuerungsseite einen konkreten Paketnamen eingeben. Alle gültigen Pakete aus den eingerichteten APT-Quellen sind zugelassen; keine URLs, lokalen .deb-Dateien oder Shelloptionen.','/ki Install nginx recognizes an installation request and prepares an APT plan. /ki_install nginx requests a plan without AI. Enter a concrete package name on Control. Valid packages from configured APT repositories are allowed; URLs, local .deb files and shell options are not.','/ki Instala nginx reconoce la solicitud y prepara un plan APT. /ki_install nginx lo pide sin IA. En Control introduce un paquete concreto. Se permiten paquetes válidos de repositorios configurados; no URLs, archivos .deb locales ni opciones shell.','/ki Installe nginx reconnaît la demande et prépare un plan APT. /ki_install nginx demande le plan sans IA. Dans Commandes, saisissez un paquet précis. Les paquets valides des dépôts APT configurés sont autorisés ; pas d’URL, fichier .deb local ni option shell.'),
 ('Zielpaket und alle Abhängigkeiten samt Versionen prüfen, dann separat bestätigen. Freigaben sind einmalig, identitäts- und nachrichtengebunden und zwei Minuten gültig. Ein geänderter Plan wird abgewiesen. Bereits installierte Zielpakete werden nicht erneut installiert.','Review the target package and all dependencies with versions, then confirm separately. Approvals are one-time, bound to identity/message and valid for two minutes. Changed plans are rejected. Already installed targets are not reinstalled.','Revisa el paquete y todas las dependencias con versiones, y confirma aparte. La autorización es de un uso, ligada a identidad/mensaje y válida dos minutos. Se rechazan planes cambiados. No reinstala objetivos ya instalados.','Vérifiez le paquet et toutes ses dépendances avec versions, puis confirmez séparément. L’autorisation est unique, liée à l’identité/message et valable deux minutes. Un plan modifié est refusé. Les paquets cibles déjà installés ne sont pas réinstallés.'),
 ('Installiert wird auf dem Linux-Host im Hintergrund. Abhängigkeiten dürfen gemäß Plan aktualisiert werden; Paket-Skripte können Dienste neu starten. Entfernen und Herabstufen sind nicht freigegeben. /ki_install_status zeigt den letzten Auftrag. Unklare Ergebnisse niemals blind wiederholen, sondern per SSH prüfen.','Installation runs in the background on the Linux host. Dependencies may upgrade as planned; package scripts can restart services. Removal and downgrades are not permitted. /ki_install_status shows the last job. Never blindly retry uncertain results; inspect through SSH.','La instalación corre en segundo plano en el host Linux. Puede actualizar dependencias según el plan y reiniciar servicios mediante scripts. No permite eliminar ni bajar versiones. /ki_install_status muestra la última tarea. No repitas resultados inciertos; revisa por SSH.','L’installation s’exécute en arrière-plan sur l’hôte Linux. Les dépendances peuvent être mises à jour selon le plan et les scripts redémarrer des services. Suppressions et rétrogradations sont interdites. /ki_install_status affiche la dernière tâche. Ne répétez pas un résultat incertain ; vérifiez via SSH.'),
])

guide('control','functions',('Steuerbefehle & Server-Neustart','Commands and server restart','Comandos y reinicio del servidor','Commandes et redémarrage serveur'),[
 ('Telegram: /status, /ram, /disk, /uptime und /diagnose lesen Status beziehungsweise erstellen eine KI-Diagnose. /ki beantwortet Fragen oder plant Installationen. Discord stellt /status, /ki, /ki_install, /ki_install_status und die Automatikbefehle bereit. Die Bots bieten nicht exakt denselben Befehlsumfang.','Telegram: /status, /ram, /disk, /uptime and /diagnose read status or prepare an AI diagnosis. /ki answers questions or plans installs. Discord provides /status, /ki, /ki_install, /ki_install_status and automation commands. The bots do not have identical command sets.','Telegram: /status, /ram, /disk, /uptime y /diagnose consultan estado o crean diagnóstico de IA. /ki responde o planifica instalaciones. Discord ofrece /status, /ki, /ki_install, /ki_install_status y automatización. Los bots no tienen comandos idénticos.','Telegram : /status, /ram, /disk, /uptime et /diagnose lisent l’état ou préparent un diagnostic IA. /ki répond ou planifie des installations. Discord propose /status, /ki, /ki_install, /ki_install_status et les commandes d’automatisation. Les deux bots n’ont pas exactement les mêmes commandes.'),
 ('Auf Steuerung stehen lesende Abfragen, bestätigte RAID-Monitor-Reparatur, Automatikschalter, Übungs-/Bestätigungstest und Paketinstallation. Abbrechen verbraucht keine tatsächliche Reparatur. Der Übungsdienst ist kein produktiver Anwendungsdienst.','Control offers read-only queries, confirmed RAID-monitor repair, automation switches, practice/confirmation tests and package installation. Cancel does not perform a repair. The practice service is not a production application service.','Control ofrece consultas de lectura, reparación confirmada del monitor RAID, automatización, pruebas y paquetes. Cancelar no ejecuta reparación. El servicio de práctica no es una aplicación productiva.','Commandes propose des lectures, la réparation confirmée du moniteur RAID, les interrupteurs d’automatisation, les tests et l’installation de paquets. Annuler n’effectue aucune réparation. Le service d’exercice n’est pas une application de production.'),
 ('Server-Neustart betrifft den gesamten Host. Erst nach Dialogbestätigung und Eingabe des angezeigten Wortes wird ein fester Neustartauftrag mit etwa zehn Sekunden Verzögerung angelegt. Bots und Webseite sind dann zeitweise offline. Ein angeforderter Neustart bestätigt nicht dessen Abschluss.','Server restart affects the whole host. A fixed restart request with about ten seconds delay is created only after confirmation and typing the displayed word. Bots and website temporarily go offline. A requested restart does not confirm completion.','Reiniciar servidor afecta a todo el host. Solo se programa tras confirmar y escribir la palabra indicada, con unos diez segundos de demora. Bots y web quedan temporalmente sin conexión. Solicitar reinicio no confirma que haya terminado.','Redémarrer le serveur concerne tout l’hôte. Une demande fixe avec environ dix secondes de délai est créée après confirmation et saisie du mot affiché. Bots et site sont temporairement hors ligne. Une demande ne confirme pas la fin du redémarrage.'),
])

guide('console','functions',('SSH Console: Aktivitäten lesen','SSH Console: reading activity','Consola SSH: consultar actividad','Console SSH : lire l’activité'),[
 ('Die SSH Console ist eine lesende Aktivitätsansicht, keine interaktive Shell. Sie zeigt feste Bearbeitungsphasen der KI seit dem letzten Bot-Neustart sowie die jüngsten Paket- und Webaufträge. Fragen, Antworten und Tokens erscheinen nicht.','SSH Console is a read-only activity view, not an interactive shell. It shows fixed AI processing phases since the last bot restart and recent package/web jobs. Questions, answers and tokens are excluded.','La consola SSH es una vista de actividad de solo lectura, no un terminal interactivo. Muestra fases de IA desde el último reinicio del bot y tareas recientes. Excluye preguntas, respuestas y tokens.','La console SSH est une vue d’activité en lecture seule, pas un shell interactif. Elle affiche les phases de l’IA depuis le dernier redémarrage du bot et les tâches récentes. Questions, réponses et tokens sont exclus.'),
 ('APT-Fortschritt wird nur aus bekannten Zeilen und Paketnamen des tatsächlichen Plans gewonnen. Keine rohen Ausgaben von Installationsskripten. Erstellungszeiten sind ausdrücklich so bezeichnet; Schritte ohne Einzelzeit erhalten keine erfundene Uhrzeit. Bei fehlendem Adapter bleibt die Seite mit Hinweis erhalten.','APT progress is extracted only from known lines and package names in the actual plan. Raw installation script output is excluded. Creation times are labeled; steps without timestamps receive no invented time. Without an adapter the page remains with an explanation.','El progreso APT se extrae solo de líneas conocidas y paquetes del plan real. No muestra salida bruta de scripts. Las horas de creación se etiquetan; no inventa horas para pasos sin marca. Sin adaptador la página mantiene una explicación.','La progression APT provient uniquement de lignes connues et des paquets du vrai plan. Les sorties brutes des scripts sont exclues. Les heures de création sont indiquées ; aucun horaire n’est inventé. Sans adaptateur, la page reste avec une explication.'),
])

guide('backup','operations',('Sicherungen & Wiederherstellung','Backups and recovery','Copias de seguridad y recuperación','Sauvegardes et restauration'),[
 ('Die verwaltete Linux-Installation sichert täglich um 03:15 Europe/Berlin nach /var/backups/kiagent-daily. Archive enthalten private Zugangsdaten und einen konsistenten SQLite-Snapshot und sind nur für root lesbar. Es gibt keine automatische Löschung alter Archive; freien Platz überwachen.','The managed Linux installation backs up daily at 03:15 Europe/Berlin to /var/backups/kiagent-daily. Archives contain private credentials and a consistent SQLite snapshot and are root-only. Old archives are not automatically deleted; monitor free space.','La instalación Linux administrada respalda cada día a las 03:15 Europe/Berlin en /var/backups/kiagent-daily. Contiene credenciales y una copia SQLite coherente, solo legible por root. No borra archivos antiguos automáticamente; vigila el espacio.','L’installation Linux gérée sauvegarde chaque jour à 03:15 Europe/Berlin dans /var/backups/kiagent-daily. Les archives contiennent des secrets et un instantané SQLite cohérent, lisibles uniquement par root. Aucune suppression automatique des anciennes archives ; surveillez l’espace.'),
 ('Eine isolierte Wiederherstellungsprüfung bestätigt Dateien und Datenbankkonsistenz, keinen vollständigen neuen Server. Backups auf demselben RAID schützen nicht vor dessen vollständigem Verlust. Externe Sicherung separat planen. Niemals Archive, Volumes oder Auth-Dateien veröffentlichen.','Isolated restore checks verify files and database consistency, not a complete new server. Backups on the same RAID do not protect against total array loss. Plan external backups separately. Never publish archives, volumes or auth files.','Las pruebas aisladas verifican archivos y coherencia de base de datos, no un servidor nuevo completo. Las copias en el mismo RAID no protegen ante pérdida total. Planifica copias externas aparte. No publiques archivos, volúmenes ni autenticación.','Les tests isolés vérifient fichiers et cohérence de base, pas un nouveau serveur complet. Les sauvegardes sur le même RAID ne protègent pas d’une perte totale. Prévoyez des copies externes séparément. Ne publiez jamais archives, volumes ou fichiers d’authentification.'),
 ('Bei Wiederherstellung Dienste kontrolliert anhalten, Besitz/Rechte prüfen und keine alte Historie auf ein bereits weitergelaufenes System zurückspielen. Sonst könnten verbrauchte Freigaben wiederverwendbar werden. Web-Passwortzustand liegt separat und ist nicht Teil der täglichen Konfigurationssicherung; bei Wiederherstellung administrativ neu setzen.','For recovery stop services deliberately, verify ownership/permissions and do not restore old history onto a system that has continued running. That could reuse consumed approvals. Web password state is separate and not part of the daily configuration backup; reset it administratively during recovery.','Al recuperar detén servicios de forma controlada, verifica permisos y no restaures historial antiguo sobre un sistema que siguió operando. Podría reutilizar autorizaciones consumidas. La contraseña web queda aparte y no está en el respaldo diario; restablécela administrativamente.','Pour restaurer, arrêtez les services de façon contrôlée, vérifiez propriétaires/droits et ne restaurez pas un ancien historique sur un système ayant continué à fonctionner. Des autorisations consommées pourraient redevenir utilisables. L’authentification web est séparée et exclue de la sauvegarde quotidienne ; réinitialisez-la administrativement.'),
])

guide('maintenance','operations',('Updates, Version & Fehlerhilfe','Updates, version and troubleshooting','Actualizaciones, versión y solución de problemas','Mises à jour, version et dépannage'),[
 ('Die Produktversion steht unten im Menü. Die aktuelle Veröffentlichung trägt die Version 1.0.0.1. Updates werden ausdrücklich aus einem geprüften Quellstand installiert; es gibt kein unbeaufsichtigtes Selbst-Update. Vorher offene oder unklare Aufträge prüfen und Sicherungen kontrollieren.','The product version appears at the bottom of the menu. The current release is version 1.0.0.1. Updates are explicitly installed from reviewed source; there is no unattended self-update. Check open/uncertain jobs and backups first.','La versión aparece abajo en el menú. La publicación actual tiene la versión 1.0.0.1. Las actualizaciones se instalan explícitamente desde código revisado; no hay autoactualización desatendida. Revisa tareas abiertas/inciertas y respaldos antes.','La version apparaît en bas du menu. La version actuelle est 1.0.0.1. Les mises à jour s’installent explicitement depuis des sources vérifiées ; aucune mise à jour autonome. Vérifiez d’abord tâches ouvertes/incertaines et sauvegardes.'),
 ('Auf bestehender verwalteter Installation tools/install_ui.py aus dem vorbereiteten Stand mit sudo starten. Das Skript testet isoliert, sichert Code und Images und prüft den Neustart. Zugangsdaten, Passwort, Historie und Sperrzeiten bleiben erhalten. Danach Browser mit Strg+F5 neu laden.','On an existing managed installation run tools/install_ui.py from the prepared source with sudo. It tests in isolation, backs up code/images and checks restart. Credentials, password, history and lock times are preserved. Afterwards reload the browser with Ctrl+F5.','En una instalación administrada existente ejecuta tools/install_ui.py desde el código preparado con sudo. Prueba aisladamente, respalda código/imágenes y comprueba reinicio. Conserva credenciales, contraseña, historial y bloqueos. Recarga con Ctrl+F5.','Sur une installation gérée existante, lancez tools/install_ui.py depuis les sources préparées avec sudo. Il teste isolément, sauvegarde code/images et vérifie le redémarrage. Secrets, mot de passe, historique et délais sont conservés. Rechargez avec Ctrl+F5.'),
 ('Bei 502 oder fehlender Bot-Antwort zunächst Dienstzustände, Container-Gesundheit und gespeichertes Installationsergebnis per SSH lesen. Bei KI-Fehlern OpenAI-Konfiguration und Projektzugang prüfen; /status und /ki_install bleiben unabhängig von KI. Bei Cookie-Fehlern Anmeldung neu öffnen und Cookies zulassen.','For 502 or a silent bot first read service states, container health and the saved installation report over SSH. For AI errors check OpenAI configuration/project access; /status and /ki_install remain independent of AI. For cookie errors reopen sign-in and allow cookies.','Ante 502 o un bot silencioso consulta estados, salud de contenedores e informe guardado por SSH. Para errores de IA revisa OpenAI y acceso al proyecto; /status y /ki_install no dependen de IA. Ante errores de cookies reabre acceso y permítelas.','En cas de 502 ou bot silencieux, lisez d’abord états des services, santé des conteneurs et rapport d’installation via SSH. Pour les erreurs IA, vérifiez OpenAI et l’accès au projet ; /status et /ki_install sont indépendants. En cas d’erreur de cookie, rouvrez la connexion et autorisez les cookies.'),
 ('Keine Tokens oder unbereinigten Journale in öffentliche Issues kopieren. Ein unklarer Aktionsausgang wird nicht automatisch wiederholt. Bei eigener Anpassung die installierten Dateien vor einem Update mit dem Projektstand vergleichen.','Do not paste tokens or unsanitized journals into public issues. Uncertain actions are never retried automatically. If you customized the installation, compare installed files with the project before upgrading.','No pegues tokens ni registros sin limpiar en incidencias públicas. Las acciones inciertas no se repiten automáticamente. Si personalizaste la instalación compara archivos con el proyecto antes de actualizar.','Ne copiez pas de tokens ou journaux non nettoyés dans des tickets publics. Les actions incertaines ne sont jamais répétées automatiquement. Si vous avez personnalisé l’installation, comparez les fichiers au projet avant mise à jour.'),
],commands=('systemctl is-active kiagent-config kiagent-docker kiagent-executor kiagent-packages','sudo python3 tools/install_ui.py'))

LINK_LABELS={
 'Telegram tutorial':('Telegram-Anleitung','Telegram tutorial','Guía de Telegram','Guide Telegram'),
 'Discord IDs':('Discord-IDs finden','Find Discord IDs','Encontrar IDs de Discord','Trouver les identifiants Discord'),
 'Discord developer guide':('Discord-Entwickleranleitung','Discord developer guide','Guía para desarrolladores de Discord','Guide de développement Discord'),
 'OpenAI API keys':('OpenAI-API-Schlüssel','OpenAI API keys','Claves API de OpenAI','Clés API OpenAI'),
 'OpenAI production guidance':('OpenAI: sicherer Betrieb','OpenAI production guidance','OpenAI: uso seguro','OpenAI : exploitation sûre'),
 'Healthchecks checks':('Healthchecks verwalten','Manage Healthchecks','Gestionar Healthchecks','Gérer Healthchecks'),
 'Healthchecks documentation':('Healthchecks-Dokumentation','Healthchecks documentation','Documentación de Healthchecks','Documentation Healthchecks'),
}
def documents(lang):
 return [{**row,'title':tr(row['title'],lang),'category_title':tr(CATEGORIES[row['category']],lang),'steps':[tr(step,lang) for step in row['steps']],
          'links':[(tr(LINK_LABELS[label],lang) if label in LINK_LABELS else label,link) for label,link in row['links']]} for row in GUIDES]

def categories(lang):
 return [{'key':key,'title':tr(title,lang),'documents':[row for row in documents(lang) if row['category']==key]} for key,title in CATEGORIES.items()]
